mapper.select:
SELECT 
FROM account_online_attempt_log
WHERE online_attempt_id = #{onlineAttemptId}
ORDER BY occurred_at ASC, id ASC
LIMIT #{limit}

SELECT 
FROM account_online_attempt_log
WHERE account_id = #{accountId}
ORDER BY occurred_at DESC, id DESC
LIMIT #{limit}

SELECT id
FROM account_online_attempt_log
WHERE tenant_id = #{tenantId}
  AND account_id = #{accountId}
  AND online_attempt_id = #{onlineAttemptId}
  AND occurred_at = #{occurredAt}
  AND to_state = 'PROXY_FAILED'
  AND diagnosis_class = 'STATE_CHANGED'
LIMIT 1 FOR UPDATE

mapper.delete:
DELETE FROM account_online_attempt_log
WHERE occurred_at < #{cutoff}
ORDER BY occurred_at ASC, id ASC
LIMIT #{limit}
